	\end{equation*}

Assume towards a contradiction that there exists a protocol $\ensuremath{\pi}_r$ with $r$-rounds, 
\begin{equation*}
	\ensuremath{\textnormal{\textsf{suc}}}(\ensuremath{\pi}_r, \ensuremath{\mathcal{G}}_r(n_r)) \geqslant 15/16, \qquad \textnormal{ and }  \qquad \ensuremath{\textnormal{\textsf{bw}}}(\ensuremath{\pi}_r) = s < n_r^{(1/2) \cdot (1/34^r)} \cdot \frac1{(480)^2}.
\end{equation*}
We prove the theorem by repeatedly applying \Cref{lem:round-elim} for $r$ times on protocol $\ensuremath{\pi}_r$, to get a protocol $\ensuremath{\pi}_0$ for $\ensuremath{\mathcal{G}}_0(n_0)$. 
The value of $n_0$, using \Cref{eq:params-r-1} is $n_0 = {n_1}^{1/34} = \cdots = {n_r}^{1/34^r}$. 	From the large value of $n_r$ in the statement of the theorem, we have, 
\begin{equation}\label{eq:inter-thm-1}
	n_0 = n_r^{1/34^r} > r^4. 
\end{equation}
The probability of success of $\ensuremath{\pi}_0$ is at least, 
\begin{align*}
	&\ensuremath{\textnormal{\textsf{suc}}}(\ensuremath{\pi}_r, \ensuremath{\mathcal{G}}_r(n_r)) - \sum_{\ell = 1}^r \frac1{n_{r-\ell}} - 15 \cdot \sqrt{s} \cdot  \sum_{\ell = 1}^r \frac1{(n_{r-\ell})^{1/2}} \\
	&\geqslant \frac{15}{16} - \sum_{\ell = 1}^r \frac1{n_{r-\ell}} - 15 \cdot \sqrt{s} \cdot  \sum_{\ell = 1}^r \frac1{(n_{r-\ell})^{1/2}} \tag{by value of $\ensuremath{\textnormal{\textsf{suc}}}(\ensuremath{\pi}_r, \ensuremath{\mathcal{G}}_r(n_r))$ from the theorem statement} \\
	&\geqslant  \frac{15}{16} - r \cdot (\frac1{n_0}) - 15 \cdot \sqrt{s} \cdot  r \cdot (\frac1{n_0^{1/2}}) \tag{as $n_0, n_1, \ldots, n_{r-1}$ are increasing} \\
	&\geqslant  \frac{15}{16} - \frac{1}{32} - 15 \cdot \sqrt{s} \cdot  r \cdot (\frac1{n_0^{1/2}}) \tag{as $r  < 32 n_0$ from \Cref{eq:inter-thm-1}} \\
	&\geqslant \frac{29}{32} - 15 \cdot \frac1{480} \cdot r \cdot (1/n_0^{-0.25}) \tag{by value of $s$, and $n_0 = n_r^{1/34^r}$} \\
	&> \frac{29}{32} - \frac1{32} \tag{as $r < {n_0}^{1/4}$ from \Cref{eq:inter-thm-1}} > \frac78.
\end{align*}
This contradicts \Cref{clm:0-round-prot}, thereby proving the theorem.

