&\hspace{30pt}=   \mi{\rMinner{x\to u_j}}{\rMinner{x}(-u_j)  \mid\ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNinner{x}{}, \rNpub{x}, \rMpub{x}} \tag{by definition of $\ensuremath{\rv{W}_{\textnormal{cond}}}$} \\
