\begin{align*}
	&\ensuremath{\rv{G}}_{r-1} \times (\ensuremath{\rv{ids}}, \ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}})\\
	&~\eqcolor{\times (\bigtimes_{x \in G_{r-1}} \rNpub{x}, \rMpub{x} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNinner{x}{})}  \\
	&\times (\bigtimes_{x \in G_{r-1}}\bigtimes_{\substack{y \in G_{r-1} \\y \notin X}}  (\rMinner{x}(y) \mid  \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNpub{x}, \rMpub{x}, \rNinner{x}{})   \\
	&\times (\bigtimes_{x \in G_{r-1}}  \rNrest{x} \mid \rMinner{x}, \rNinner{x}{}, \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNpub{x}, \rMpub{x}). 
