	First, we have, 
	\begin{align*}
		&	\mi{\rMpub{x}, \rNpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}} \\
		&\hspace{30pt}= \mi{\rNpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}} + \mi{\rMpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNpub{x}} \tag{by the chain rule of mutual information \Cref{fact:it-facts}-(\ref{part:chain-rule})\xspace} \\
		&\hspace{30pt} = 0 + \mi{\rMpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNpub{x}}  \tag{by \Cref{obs:re-inter1} and by \Cref{fact:it-facts}-(\ref{part:info-zero})\xspace} \\
		&\hspace{30pt}= 	\mi{\rMpub{x}}{\rNinner{x}{} \mid \eqcolor{\ridlayer{X}, \ridlayer{Y}, \ridlayer{Z}, \ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}}, \rNpub{x}}. \tag{expanding $\ensuremath{\rv{aux}}$ and $\ensuremath{\rv{ids}}$} \\
		&\hspace{30pt}= 	\mi{\rMpub{x}}{\eqcolor{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}]} \mid \ridlayer{X}, \ridlayer{Y}, \ridlayer{Z}, \ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}, \rNpub{x}}. \tag{as $\rNinner{x}{}$ is fixed by $\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}]$ when the identities are unique}
	\end{align*}
We use $\ensuremath{\rv{W}_{\textnormal{rest}}} $ to denote the random variables $ \ridlayer{X}$, $\ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}, \rNpub{x}$ and all random variables in $\ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}$ barring $\rcJup{x}$. These random variables are bundled together as they are not relevant to the rest of the argument. 
\begin{align*}
	&	\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{X}, \ridlayer{Y}, \ridlayer{Z}, \ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}, \rNpub{x}} \\
	&\hspace{30pt}= 	\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y}, \ridlayer{Z}, \rcJup{x}, \eqcolor{\ensuremath{\rv{W}_{\textnormal{rest}}}}} \\
	&\hspace{30pt}= 	\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \eqcolor{\ridlayer{Y} \cup \ridlayer{Z}}, \rcJup{x}, \ensuremath{\rv{W}_{\textnormal{rest}}}},
	\intertext{
where for the last equality, we have used that $\ridlayer{Y} \cup \ridlayer{Z}$ is fixed by $\ridlayer{Y}, \ridlayer{Z} $ and vice-versa. This is because $\ridlayer{Y} = \{\ridlayer{Y} \cup \ridlayer{Z}\} \cap Y$ and $\ridlayer{Z} = \{\ridlayer{Y} \cup \ridlayer{Z}\} \cap Z$ as they are disjoint. We continue, }


		&\hspace{30pt}= \mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \eqcolor{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\}}, \ensuremath{\rv{W}_{\textnormal{rest}}}}, 
\end{align*}
where, the last step is true because $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\}, \ridlayer{Y} \cup \ridlayer{Z}$ is fixed by $\rcJup{x}, \ridlayer{Y} \cup \ridlayer{Z}$ and vice-versa (the elements in $\rcJup{x}$ are disjoint from all the elements in $\ridlayer{Y} \cup \ridlayer{Z}$ by definition). 

We know that $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\}$ is a collection of size $\alpha_r + 1$, where each set has $2n_{r-1}$ elements ($n_{r-1}$ ones from each of  $Y$ and $Z$). We condition on this collection being sets $\ensuremath{\mathcal{J}} = (J_1, J_2, \ldots, J_{\alpha_r + 1})$ in the next step and have, 
\begin{align*}
&\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\}, \ensuremath{\rv{W}_{\textnormal{rest}}}} \\
&= \eqcolor{\ensuremath{{\mathbb{E}}}_{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}}}\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \eqcolor{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}}, \ensuremath{\rv{W}_{\textnormal{rest}}}}. \tag{by the definition of conditional mutual information}
\end{align*}
We prove the statement separately for each collection $\ensuremath{\mathcal{J}}$. 

Now, we argue that conditioned on $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}$, the value of $\ridlayer{Y} \cup \ridlayer{Z}$ is uniform over all the sets in collection $\ensuremath{\mathcal{J}}$. Random variable $\rcJup{x}$ is made of $\alpha_r$ disjoint collections, each with $n_{r-1}$ elements from each of $Y$ and $Z$. Moreover, both $\rcJup{x}$ and $\ridlayer{Y} \cup \ridlayer{Z}$ are chosen uniformly at random such that the sets in $\rcJup{x}$ and $\ridlayer{Y} \cup \ridlayer{Z}$ are disjoint. Hence, given that  $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}$, $\ridlayer{Y} \cup \ridlayer{Z}$ can be any set in this collection chosen uniformly. We continue as, 
\begin{align*}
&\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}, \ensuremath{\rv{W}_{\textnormal{rest}}}} \\
&= \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},  \ridlayer{Y} \cup \ridlayer{Z} = J_i,  \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}}.
\end{align*}

We will prove that the joint distribution of all the random variables in the mutual information term is independent of the event $\{\ridlayer{Y} \cup \ridlayer{Z}\} = J_i$ conditioned on the event $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}$. We will go over the terms one by one, and for each term, we also condition on the preceding terms.  
\begin{itemize}
	\item $\rNbtogether{x}{}[J_i]$ for $i \in [\alpha_r + 1]$: all these subsets are sampled from $\ensuremath{\ensuremath{\mathcal{D}}_{\textnormal{in}}}$ independently of each other. The value of set $\ridlayer{Y} \cup \ridlayer{Z} $ inside collection $\ensuremath{\mathcal{J}}$ has no correlation with the joint distribution of these inputs.
	\item $\rNbhood{x}{Y}{}, \rNbhood{x}{Z}{}$: this is the input of vertex $x$. These variables can only be correlated to the event $\ridlayer{Y} \cup \ridlayer{Z}  = J_i$ through random variables $\rNbtogether{x}{}[J_i]$ for $i \in [\alpha_r + 1]$, which we have just argued is independent of the event. 
	\item $\ensuremath{\rv{W}_{\textnormal{rest}}}$: this has random variable $\rNpub{x}$, which are channel types of $x$ to vertices disjoint from collection $\ensuremath{\mathcal{J}}$ (and independent of what happens inside $\ensuremath{\mathcal{J}}$), and the other random variables $\ridlayer{X}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}$, $\ensuremath{\bm{L}_{\textnormal{all}}}$, all $\rcJup{w}$ for $w \neq x$.  These other variables are disjoint from $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\}$, and are independent of the value of set $\ridlayer{Y} \cup \ridlayer{Z}$ inside collection $\ensuremath{\mathcal{J}}$.
	\item $\rMpub{x}$: these are the messages that $x$ sends to specific indices in $\rLupdown{x \to Y}{t, j}$ for each other layer $Y$, type $t \in [r] \cup \{0\}$ and $j \in [n_{r-1}]$. We have argued that the input to vertex $x$ is independent of the identity of $\ridlayer{Y} \cup \ridlayer{Z}$ inside collection $\ensuremath{\mathcal{J}}$. As the protocol $\ensuremath{\pi}_r$ is deterministic, $\rMpub{x}$ is fixed by $\rNbhood{x}{Y}{}, \rNbhood{x}{Z}{}, \rid{x}$, and is independent of the event $\ridlayer{Y} \cup \ridlayer{Z} = J_i$. 
\end{itemize}
Thus, the joint distribution of all the random variables is independent of the value of $\{\ridlayer{Y} \cup \ridlayer{Z}\}$ inside collection $\ensuremath{\mathcal{J}}$. The mutual information term then becomes, 
\begin{align*}
	& \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},  \eqcolor{\ridlayer{Y} \cup \ridlayer{Z} = J_i},  \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \\
	 &\hspace{30pt}= 	 \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},   \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \\
	 &\hspace{30pt}\leqslant  \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},  \eqcolor{\rNbtogether{x}{}[J_1], \ldots, \rNbtogether{x}{}[J_{i-1}]}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}},
\end{align*}
where for the last step we have used that $\rNbtogether{x}{}[J_i] \perp \rNbtogether{x}{}[J_k] \mid \ensuremath{\rv{W}_{\textnormal{rest}}}$, $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}$ for any $i, k \in [\alpha_r+1]$ with $i \neq k$, and thus we can apply \Cref{prop:info-increase}. The independence of $\rNbtogether{x}{}[J_i]$ and $\rNbtogether{x}{}[J_k]$ follows because, conditioned on $\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}$, both these variables are sampled from $\ensuremath{\ensuremath{\mathcal{D}}_{\textnormal{in}}}$ independently of each other. The value of $\ensuremath{\rv{W}_{\textnormal{rest}}}$ does not affect this independence either, as $\ensuremath{\rv{W}_{\textnormal{rest}}}$ is made of $\ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}, \ridlayer{X}$ , $\rcJup{w}$ for $w \neq x$, all of which are disjoint from $\ensuremath{\mathcal{J}}$ and $\rNpub{x}$ consisting of channel types to $x$ disjoint from collection $\ensuremath{\mathcal{J}}$. 
We proceed with the proof as follows.
\begin{align*}
&	 \frac1{\alpha_r + 1} \cdot \eqcolor{\sum_{i \in [\alpha_r + 1]}} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}}, \eqcolor{\rNbtogether{x}{}[J_1], \ldots, \rNbtogether{x}{}[J_{i-1}]}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \\
	 &= \frac{1}{\alpha_r + 1} \cdot \mi{\rMpub{x}}{\eqcolor{\rNbtogether{x}{}[J_1], \rNbtogether{x}{}[J_2], \ldots, \rNbtogether{x}{}[J_{\alpha_r + 1}]} \mid \ensuremath{\rv{W}_{\textnormal{rest}}}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \tag{by the chain rule of mutual information in \Cref{fact:it-facts}-(\ref{part:chain-rule})\xspace}\\
	 &\leqslant \frac1{\alpha_r + 1} \cdot \en{\rMpub{x} \mid \ensuremath{\rv{W}_{\textnormal{rest}}}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \tag{by \Cref{fact:it-facts}-(\ref{part:info-entropy})\xspace} \\
	 &\leqslant \frac1{\alpha_r + 1} \cdot s \cdot 2\gamma_r  \cdot (r+1) \cdot n_{r-1}. \tag{by~\Cref{fact:it-facts}-(\ref{part:uniform})\xspace, \Cref{obs:public-msgs-number}, and as the length of each message is bounded by $s$}
\end{align*}
To finish the proof, we get, 
\begin{align*}
\mi{\rMpub{x}, \rNpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}} &\leqslant  \ensuremath{{\mathbb{E}}}_{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \bracket{\frac1{\alpha_r + 1} \cdot s \cdot 2\gamma_r  \cdot (r+1) \cdot n_{r-1}} \\
&= \frac1{\alpha_r + 1} \cdot s \cdot 2\gamma_r   \cdot (r+1) \cdot n_{r-1}. \qedhere
\end{align*}

\begin{align*}
		&	\mi{\rMpub{x}, \rNpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}} \\
		&\hspace{30pt}= \mi{\rNpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}} + \mi{\rMpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNpub{x}} \tag{by the chain rule of mutual information \Cref{fact:it-facts}-(\ref{part:chain-rule})\xspace} \\
		&\hspace{30pt} = 0 + \mi{\rMpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNpub{x}}  \tag{by \Cref{obs:re-inter1} and by \Cref{fact:it-facts}-(\ref{part:info-zero})\xspace} \\
		&\hspace{30pt}= 	\mi{\rMpub{x}}{\rNinner{x}{} \mid \eqcolor{\ridlayer{X}, \ridlayer{Y}, \ridlayer{Z}, \ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}}, \rNpub{x}}. \tag{expanding $\ensuremath{\rv{aux}}$ and $\ensuremath{\rv{ids}}$} \\
		&\hspace{30pt}= 	\mi{\rMpub{x}}{\eqcolor{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}]} \mid \ridlayer{X}, \ridlayer{Y}, \ridlayer{Z}, \ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}, \rNpub{x}}. \tag{as $\rNinner{x}{}$ is fixed by $\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}]$ when the identities are unique}
	\end{align*}

\begin{align*}
	&	\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{X}, \ridlayer{Y}, \ridlayer{Z}, \ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}, \ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}, \ensuremath{\bm{L}_{\textnormal{all}}}, \rNpub{x}} \\
	&\hspace{30pt}= 	\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y}, \ridlayer{Z}, \rcJup{x}, \eqcolor{\ensuremath{\rv{W}_{\textnormal{rest}}}}} \\
	&\hspace{30pt}= 	\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \eqcolor{\ridlayer{Y} \cup \ridlayer{Z}}, \rcJup{x}, \ensuremath{\rv{W}_{\textnormal{rest}}}},
	\intertext{
where for the last equality, we have used that $\ridlayer{Y} \cup \ridlayer{Z}$ is fixed by $\ridlayer{Y}, \ridlayer{Z} $ and vice-versa. This is because $\ridlayer{Y} = \{\ridlayer{Y} \cup \ridlayer{Z}\} \cap Y$ and $\ridlayer{Z} = \{\ridlayer{Y} \cup \ridlayer{Z}\} \cap Z$ as they are disjoint. We continue, }


		&\hspace{30pt}= \mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \eqcolor{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\}}, \ensuremath{\rv{W}_{\textnormal{rest}}}}, 
\end{align*}

\begin{align*}
&\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\}, \ensuremath{\rv{W}_{\textnormal{rest}}}} \\
&= \eqcolor{\ensuremath{{\mathbb{E}}}_{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}}}\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \eqcolor{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}}, \ensuremath{\rv{W}_{\textnormal{rest}}}}. \tag{by the definition of conditional mutual information}
\end{align*}

\begin{align*}
&\mi{\rMpub{x}}{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] \mid \ridlayer{Y} \cup \ridlayer{Z}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}, \ensuremath{\rv{W}_{\textnormal{rest}}}} \\
&= \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},  \ridlayer{Y} \cup \ridlayer{Z} = J_i,  \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}}.
\end{align*}

\begin{align*}
	& \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},  \eqcolor{\ridlayer{Y} \cup \ridlayer{Z} = J_i},  \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \\
	 &\hspace{30pt}= 	 \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},   \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \\
	 &\hspace{30pt}\leqslant  \frac1{\alpha_r + 1} \cdot \sum_{i \in [\alpha_r + 1]} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}},  \eqcolor{\rNbtogether{x}{}[J_1], \ldots, \rNbtogether{x}{}[J_{i-1}]}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}},
\end{align*}

\begin{align*}
&	 \frac1{\alpha_r + 1} \cdot \eqcolor{\sum_{i \in [\alpha_r + 1]}} \mi{\rMpub{x}}{\rNbtogether{x}{}[J_i] \mid \ensuremath{\rv{W}_{\textnormal{rest}}}, \eqcolor{\rNbtogether{x}{}[J_1], \ldots, \rNbtogether{x}{}[J_{i-1}]}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \\
	 &= \frac{1}{\alpha_r + 1} \cdot \mi{\rMpub{x}}{\eqcolor{\rNbtogether{x}{}[J_1], \rNbtogether{x}{}[J_2], \ldots, \rNbtogether{x}{}[J_{\alpha_r + 1}]} \mid \ensuremath{\rv{W}_{\textnormal{rest}}}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \tag{by the chain rule of mutual information in \Cref{fact:it-facts}-(\ref{part:chain-rule})\xspace}\\
	 &\leqslant \frac1{\alpha_r + 1} \cdot \en{\rMpub{x} \mid \ensuremath{\rv{W}_{\textnormal{rest}}}, \rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \tag{by \Cref{fact:it-facts}-(\ref{part:info-entropy})\xspace} \\
	 &\leqslant \frac1{\alpha_r + 1} \cdot s \cdot 2\gamma_r  \cdot (r+1) \cdot n_{r-1}. \tag{by~\Cref{fact:it-facts}-(\ref{part:uniform})\xspace, \Cref{obs:public-msgs-number}, and as the length of each message is bounded by $s$}
\end{align*}

\begin{align*}
\mi{\rMpub{x}, \rNpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}} &\leqslant  \ensuremath{{\mathbb{E}}}_{\rcJup{x} \cup \{\ridlayer{Y} \cup \ridlayer{Z}\} = \ensuremath{\mathcal{J}}} \bracket{\frac1{\alpha_r + 1} \cdot s \cdot 2\gamma_r  \cdot (r+1) \cdot n_{r-1}} \\
&= \frac1{\alpha_r + 1} \cdot s \cdot 2\gamma_r   \cdot (r+1) \cdot n_{r-1}. \qedhere
