We know from~\Cref{obs:inter-H1H2-list}-\ref{item:wx-indep-H1}  that, 
\begin{equation}\label{eq:H1-H2-1}
\ensuremath{\mathcal{H}}_1(\rv{w}^x \mid \rv{w}^{\textnormal{start}}) = \rNpub{x}, \rMpub{x} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNinner{x}{}. 
\end{equation}
Similarly in distribution $\ensuremath{\mathcal{H}}_2$ from~\Cref{obs:inter-H1H2-list}-\ref{item:wx-indep-H2}, we get, 
\begin{equation}\label{eq:H1-H2-2}
\ensuremath{\mathcal{H}}_2(\rv{w}^x \mid \rv{w}^{\textnormal{start}})  = \rNpub{x}, \rMpub{x} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}.
\end{equation}
We can write the total variation distance as, 
\begin{align*}
&\ensuremath{{\mathbb{E}}}_{\rv{w}^{\textnormal{start}} \sim \ensuremath{\mathcal{H}}_1} \tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^x \mid \rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^x \mid \rv{w}^{\textnormal{start}})} \\
	&\hspace{30pt}\leqslant \frac1{\sqrt{2}} \cdot \ensuremath{{\mathbb{E}}}_{\rv{w}^{\textnormal{start}} \sim \ensuremath{\mathcal{H}}_1} \sqrt{\kl{\ensuremath{\mathcal{H}}_1(\rv{w}^x \mid \rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^x \mid \rv{w}^{\textnormal{start}})}} \tag{by in Pinsker's inequality \Cref{fact:pinskers}}\\
	&\hspace{30pt}\leqslant \frac1{\sqrt{2}} \cdot \sqrt{ \ensuremath{{\mathbb{E}}}_{\rv{w}^{\textnormal{start}} \sim \ensuremath{\mathcal{H}}_1} \kl{\ensuremath{\mathcal{H}}_1(\rv{w}^x \mid \rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^x \mid \rv{w}^{\textnormal{start}})}} \tag{by Jensen's inequality and concavity of square root} \\
&\hspace{30pt} =  \frac1{\sqrt{2}} \cdot \sqrt{ \ensuremath{{\mathbb{E}}}_{\ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNinner{x}{}} \kl{(\rNpub{x}, \rMpub{x} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNinner{x}{})}{(\rNpub{x}, \rMpub{x} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}})}} \tag{by \Cref{eq:H1-H2-1} and \Cref{eq:H1-H2-2}} \\
&\hspace{30pt}=  \frac1{\sqrt{2}} \cdot \sqrt{ \mi{\rNpub{x}, \rMpub{x}}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}}} \tag{by relation between KL-Divergence and mutual information \Cref{fact:kl-info}} \\
&\hspace{30pt}\leqslant \sqrt{\frac1{\alpha_r + 1} \cdot s \cdot \gamma_r  \cdot (r+1) \cdot n_{r-1}} \tag{by \Cref{clm:mi-low-public-msgs}}. \qedhere
\end{align*}

\begin{equation}\label{eq:H1-H2-1}
	\ensuremath{\mathcal{H}}_1(\rv{w}^x \mid \rv{w}^{\textnormal{start}}) = \rNpub{x}, \rMpub{x} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNinner{x}{}. 
	\end{equation}

\begin{equation}\label{eq:H1-H2-2}
	\ensuremath{\mathcal{H}}_2(\rv{w}^x \mid \rv{w}^{\textnormal{start}})  = \rNpub{x}, \rMpub{x} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}.
	\end{equation}

Firstly, by \Cref{obs:inter-H1H2-list}-\ref{item:wstart-same-H1H2}, we know that, 
\begin{equation}\label{eq:inter-wstart-H1H2}
	\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{\textnormal{start}})} = 0.
\end{equation}
We follow the lexicographic ordering on the vertices to order the random variables $\rv{w}^x$ for inner vertices $x \in G_{r-1}$. 
Let $u_1, u_2, \ldots, u_{3n_{r-1}}$ be the inner vertices with the ordering. We use $\rv{w}^{u_{<\ell}}$ to denote the joint random variable $\rv{w}^{u_1}, \rv{w}^{u_2}, \ldots, \rv{w}^{u_{\ell-1}}$ for $\ell \in [3n_{r-1}]$. We use $\rv{w}^{\textnormal{all}}$ to denote all $\rv{w}^{u_{\ell}}$ for $\ell \in [3n_{r-1}]$. 

By \Cref{obs:inter-H1H2-list}-\ref{item:wx-indep-H1H2}, we have, for any $\ell \in [3n_{r-1}]$, 
\begin{align}\label{eq:inter-wx-H1H2}
	\ensuremath{{\mathbb{E}}}_{\rv{w}^{u_{< \ell}} \sim \ensuremath{\mathcal{H}}_1}\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{< \ell}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{u_{\ell} \mid \rv{w}^{u_{< \ell}}})} &= \ensuremath{{\mathbb{E}}}_{\rv{w}^{\textnormal{start}} \sim \ensuremath{\mathcal{H}}_1} \tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{u_{\ell}} \mid \rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{u_{\ell}} \mid \rv{w}^{\textnormal{start}})} \nonumber\\
	&\leqslant \sqrt{\frac{s \cdot \gamma_r  \cdot (r+1) \cdot n_{r-1}}{\alpha_r + 1}},
\end{align}
where for the inequality we used \Cref{clm:inter-H1H2-close}. Lastly, from \Cref{obs:inter-H1H2-list}-\ref{item:wend-indep-H1H2}, we have, 
\begin{equation}\label{eq:inter-H1H2-end}
\ensuremath{{\mathbb{E}}}_{\rv{w}^{\textnormal{start}}, \rv{w}^{\textnormal{all}} \sim \ensuremath{\mathcal{H}}_1}	\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{\textnormal{end}} \mid \rv{w}^{\textnormal{start}},\rv{w}^{\textnormal{all}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{\textnormal{end}} \mid  \rv{w}^{\textnormal{start}}, \rv{w}^{\textnormal{all}})}  = 0.
\end{equation}
We can complete the proof easily now. 
\begin{align*}
	&\tvd{\ensuremath{\mathcal{H}}_1}{\ensuremath{\mathcal{H}}_2} \\
	&\hspace{30pt}\leqslant \tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{\textnormal{start}})} + \sum_{\ell \in [3n_{r-1}]} \ensuremath{{\mathbb{E}}}_{\rv{w}^{u_{< \ell}} \sim \ensuremath{\mathcal{H}}_1}\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{<\ell}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{< \ell}})} \\
	& \hspace{60pt} + 	\ensuremath{{\mathbb{E}}}_{\rv{w}^{\textnormal{start}}, \rv{w}^{\textnormal{all}} \sim \ensuremath{\mathcal{H}}_1}	\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{\textnormal{end}} \mid \rv{w}^{\textnormal{start}},\rv{w}^{\textnormal{all}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{\textnormal{end}} \mid  \rv{w}^{\textnormal{start}}, \rv{w}^{\textnormal{all}})}  \tag{by \Cref{fact:tvd-chain-rule}}\\
	&\hspace{30pt}= \sum_{\ell \in [3n_{r-1}]} \ensuremath{{\mathbb{E}}}_{\rv{w}^{u_{< \ell}} \sim \ensuremath{\mathcal{H}}_1}\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{<\ell}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{< \ell}})} \tag{by \Cref{eq:inter-wstart-H1H2} and \Cref{eq:inter-H1H2-end} first and last terms are zero} \\
