\end{align*}

\begin{equation}\label{eq:inter-wstart-H1H2}
		\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{\textnormal{start}})} = 0.
