\begin{align*}
		&\tvd{\ensuremath{\mathcal{H}}_1}{\ensuremath{\mathcal{H}}_2} \\
		&\hspace{30pt}\leqslant \tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{\textnormal{start}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{\textnormal{start}})} + \sum_{\ell \in [3n_{r-1}]} \ensuremath{{\mathbb{E}}}_{\rv{w}^{u_{< \ell}} \sim \ensuremath{\mathcal{H}}_1}\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{<\ell}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{< \ell}})} \\
		& \hspace{60pt} + 	\ensuremath{{\mathbb{E}}}_{\rv{w}^{\textnormal{start}}, \rv{w}^{\textnormal{all}} \sim \ensuremath{\mathcal{H}}_1}	\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{\textnormal{end}} \mid \rv{w}^{\textnormal{start}},\rv{w}^{\textnormal{all}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{\textnormal{end}} \mid  \rv{w}^{\textnormal{start}}, \rv{w}^{\textnormal{all}})}  \tag{by \Cref{fact:tvd-chain-rule}}\\
		&\hspace{30pt}= \sum_{\ell \in [3n_{r-1}]} \ensuremath{{\mathbb{E}}}_{\rv{w}^{u_{< \ell}} \sim \ensuremath{\mathcal{H}}_1}\tvd{\ensuremath{\mathcal{H}}_1(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{<\ell}})}{\ensuremath{\mathcal{H}}_2(\rv{w}^{u_{\ell}} \mid \rv{w}^{u_{< \ell}})} \tag{by \Cref{eq:inter-wstart-H1H2} and \Cref{eq:inter-H1H2-end} first and last terms are zero} \\
