	\end{align*}
	Let $\ensuremath{\mathcal{E}_t}$ denote the event that $\rtypeval{x, y_i} = t$. We prove the statement separately for each $t \in [r] \cup \{0\}$. 
	\begin{align*}
&	\mi{\rMinner{x}(y_i)}{\rNinner{x}{} \mid \ensuremath{\rv{ids}}, \ensuremath{\rv{aux}}, \rNpub{x}, \rMpub{x}, \ensuremath{\mathcal{E}_t}} \\
	&\hspace{30pt}= \mi{\rMinner{x}(y_i)}{\eqcolor{\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}]} \mid \eqcolor{\ridlayer{X}, \ridlayer{Y}, \ridlayer{Z}}, \ensuremath{\rv{aux}}, \rNpub{x}, \rMpub{x}, \ensuremath{\mathcal{E}_t}}. \tag{expanding $\ensuremath{\rv{ids}}$, and as $\rNinner{x}{}$ is fixed by $\rNbtogether{x}{}[\ridlayer{Y} \cup \ridlayer{Z}] $}
	\end{align*}
	Let $\rid{-y_i}$ denote the random variables $\ridlayer{Z}$ and $\rid{y'}$ for $y' \neq y_i \in G_{r-1}$, 
	and $\ensuremath{\rv{W}_{\textnormal{rest}}}$ denote the random variables $\ridlayer{X}$, $\ensuremath{\bm{\mathcal{J}}_{\textnormal{all}}}$, $\ensuremath{\bm{L}_{\textnormal{all}}}$, $\rMpub{x}, \rNpub{x}$ and all random variables in $\ensuremath{\bm{\mathcal{K}}_{\textnormal{all}}}$ barring $\rcKupdown{x \to Y}{t, i}$.
