&\hspace{30pt}=  \mi{\rMinner{x}(y_i)}{\eqcolor{\rNbtogether{x}{}[\rid{-y_i}]} \mid \rid{-y_i}, \rid{y_i}, \rcKupdown{x \to Y}{t, i}, \ensuremath{\rv{W}_{\textnormal{rest}}}, \ensuremath{\mathcal{E}_t}} \tag{as $\rNbtogether{x}{}[\rid{y_i}]$ is fixed to be $t$ conditioned on $\ensuremath{\mathcal{E}_t}$} \\
