&\hspace{30pt}= \eqcolor{\ensuremath{{\mathbb{E}}}_{\ensuremath{\mathcal{K}} \sim \rcKupdown{x \to Y}{t, i} \cup \{\rid{-y_i}\}}}   \mi{\rMinner{x}(y_i)}{\rNbtogether{x}{}[\rid{-y_i}] \mid \rid{-y_i}, \rid{y_i}, \ensuremath{\rv{W}_{\textnormal{rest}}}, \eqcolor{\rcKupdown{x \to Y}{t, i} \cup \{\rid{-y_i}\} = \ensuremath{\mathcal{K}}}, \ensuremath{\mathcal{E}_t}}. \tag{by the definition of conditional mutual information}
