\begin{align}
	\en{\rv{A}} := \sum_{A \in \supp{\rv{A}}} \ensuremath{\textnormal{Pr}}\paren{\rv{A} = A} \cdot \log{\paren{1/\ensuremath{\textnormal{Pr}}\paren{\rv{A} = A}}} \label{eq:entropy}
\end{align}

\begin{align}
\en{\rv{A} \mid \rv{B}} := \ensuremath{{\mathbb{E}}}_{B \sim \rv{B}} \bracket{\en{\rv{A} \mid \rv{B} = B}}, \label{eq:cond-entropy}
\end{align}

\begin{align}
\mi{\rv{A}}{\rv{B}} := \en{A} - \en{A \mid  B} = \en{B} - \en{B \mid  A}. \label{eq:mi}
\end{align}

\begin{align}
	\mi{\rv{A}}{\rv{B} \mid \rv{C}} = \ensuremath{{\mathbb{E}}}_{C \sim \rv{C}} \bracket{\mi{\rv{A}}{\rv{B} \mid \rv{C} = C}}. \label{eq:cond-mi}
\end{align}

\label{prop:info-increase}
  For random variables $\rv{A}, \rv{B}, \rv{C}, \rv{D}$, if $\rv{A} \perp \rv{D} \mid \rv{C}$, then, 
  \[\mi{\rv{A}}{\rv{B} \mid \rv{C}} \leqslant \mi{\rv{A}}{\rv{B} \mid  \rv{C},  \rv{D}}.\]

  Since $\rv{A}$ and $\rv{D}$ are independent conditioned on $\rv{C}$, by
  \Cref{fact:it-facts}-(\ref{part:cond-reduce})\xspace, $\ensuremath{\mathbb{H}}(\rv{A} \mid  \rv{C}) = \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{D})$ and $\ensuremath{\mathbb{H}}(\rv{A} \mid  \rv{C}, \rv{B}) \geqslant \ensuremath{\mathbb{H}}(\rv{A} \mid  \rv{C}, \rv{B}, \rv{D})$.  We have,
	 \begin{align*}
	  \mi{\rv{A}}{\rv{B} \mid  \rv{C}} &= \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{B}) = \ensuremath{\mathbb{H}}(\rv{A} \mid  \rv{C}, \rv{D}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{B}) \\
	  &\leqslant \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{D}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{B}, \rv{D}) = \mi{\rv{A}}{\rv{B} \mid \rv{C}, \rv{D}}. \nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi
	\end{align*}

\begin{align*}
	  \mi{\rv{A}}{\rv{B} \mid  \rv{C}} &= \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{B}) = \ensuremath{\mathbb{H}}(\rv{A} \mid  \rv{C}, \rv{D}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{B}) \\
	  &\leqslant \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{D}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}, \rv{B}, \rv{D}) = \mi{\rv{A}}{\rv{B} \mid \rv{C}, \rv{D}}. \nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi
	\end{align*}

\label{prop:info-decrease}
  For random variables $\rv{A}, \rv{B}, \rv{C},\rv{D}$, if $ \rv{A} \perp \rv{D} \mid \rv{B},\rv{C}$, then, 
  \[\mi{\rv{A}}{\rv{B} \mid \rv{C}} \geqslant \mi{\rv{A}}{\rv{B} \mid \rv{C}, \rv{D}}.\]

 Since $\rv{A} \perp \rv{D} \mid \rv{B},\rv{C}$, by \Cref{fact:it-facts}-(\ref{part:cond-reduce})\xspace, $\ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C}) = \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C},\rv{D})$. Moreover, since conditioning can only reduce the entropy (again by \Cref{fact:it-facts}-(\ref{part:cond-reduce})\xspace), 
  \begin{align*}
 	\mi{\rv{A}}{\rv{B} \mid  \rv{C}} &= \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C}) \geqslant \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{D},\rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C}) \\
	&= \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{D},\rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C},\rv{D}) = \mi{\rv{A}}{\rv{B} \mid \rv{C},\rv{D}}. \nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi
 \end{align*}

\begin{align*}
 	\mi{\rv{A}}{\rv{B} \mid  \rv{C}} &= \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C}) \geqslant \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{D},\rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C}) \\
	&= \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{D},\rv{C}) - \ensuremath{\mathbb{H}}(\rv{A} \mid \rv{B},\rv{C},\rv{D}) = \mi{\rv{A}}{\rv{B} \mid \rv{C},\rv{D}}. \nobreak \ifvmode \relax \else \ifdim\lastskip<1.5em \hskip-\lastskip \hskip1.5em plus0em minus0.5em \fi \nobreak \vrule height0.75em width0.5em depth0.25em\fi
 \end{align*}

\begin{align}
\kl{\mu}{\nu}:= \ensuremath{{\mathbb{E}}}_{a \sim \mu}\Bracket{\log\frac{\mu(a)}{{\nu}(a)}}. \label{eq:kl}
